#include "stdlib/math/base/special/kernel_sinf.h"

static const float S1 = -1.6666667e-01f;  // 0xBFC55555
static const float S2 = 8.3333333e-03f;   // 0x3F811111
static const float S3 = -1.9841270e-04f;  // 0xBF2A01A0
static const float S4 = 2.7557314e-06f;   // 0x3EC71DE3
static const float S5 = -2.5050760e-08f;  // 0xBE5AE5E6
static const float S6 = 1.5896910e-10f;   // 0x3DE5D93A

/**
* Computes the sine on \\( \approx \[-\pi/4, \pi/4] \\) (except on \\(-0\\)), where \\( \pi/4 \approx 0.7854 \\).
*
* ## Method
*
* -   Since \\( \sin(-x) = -\sin(x) \\), we need only to consider positive \\(x\\).
*
* -   Callers must return \\( \sin(-0) = -0 \\) without calling here since our odd polynomial is not evaluated in a way that preserves \\(-0\\). Callers may do the optimization \\( \sin(x) \approx x \\) for tiny \\(x\\).
*
* -   \\( \sin(x) \\) is approximated by a polynomial of degree \\(13\\) on \\( \left\[0,\tfrac{pi}{4}\right] \\)
*
*     ```tex
*     \sin(x) \approx x + S_1 \cdot x^3 + \ldots + S_6 \cdot x^{13}
*     ```
*
*     where
*
*     ```tex
*     \left| \frac{\sin(x)}{x} \left( 1 + S_1 \cdot x + S_2 \cdot x + S_3 \cdot x + S_4 \cdot x + S_5 \cdot x + S_6 \cdot x \right) \right| \le 2^{-58}
*     ```
*
* -   We have
*
*     ```tex
*     \sin(x+y) = \sin(x) + \sin'(x') \cdot y \approx \sin(x) + (1-x*x/2) \cdot y
*     ```
*
*     For better accuracy, let
*
*     ```tex
*     r = x^3 * \left( S_2 + x^2 \cdot \left( S_3 + x^2 * \left( S_4 + x^2 \cdot ( S_5+x^2 \cdot S_6 ) \right) \right) \right)
*     ```
*
*     then
*
*     ```tex
*     \sin(x) = x + \left( S_1 \cdot x + ( x \cdot (r-y/2) + y ) \right)
*     ```
*
* @param x    input value (in radians, assumed to be bounded by `~pi/4` in magnitude)
* @param y    tail of `x`
* @return     sine
*
* @example
* float out = stdlib_base_kernel_sinf( 3.14159f/6.0f, 0.0f );
* // returns ~0.5f
*/
float stdlib_base_kernel_sinf( const float x, const float y ) {
	float z;
	float r;
	float v;
	float w;

	z = (float)(x * x);
	w = (float)(z * z);
	r = (float)(S2 + (float)(z * (float)(S3 + (float)(z*S4))));
	r = (float)(r + (float)(z * w * (float)(S5 + (float)(z*S6))));
	v = (float)(z * x);
	if ( y == 0.0f ) {
		return (float)(x + (float)(v * (float)(S1 + (float)(z*r))));
	}
	return (float)(x - (float)((float)(z*((float)(0.5f*y) - (float)(v*r))) - y - (float)(v*S1)));
}
